 $renderRow=function(array $row,int|string $index)use($section){ ?><fieldset class="settings-row"><?php if($section==='fields')echo hidden('data[rows]['.$index.'][id]',($row['name']??'')!==''?\Kulturhus\Verein\MemberCustomFields::id($row):''); ?><legend><?= $section==='structure'?'Abteilung':($section==='fields'?'Individuelles Feld':'Briefanrede') ?></legend><div class="form-grid"><?php $fields=match($section){'salutations'=>['name'=>['Anrede','text',60,''],'personal'=>['Persönlich','text',300,''],'formal'=>['Formell','text',300,'']],'structure'=>['name'=>['Bezeichnung','text',100,''],'parent'=>['Übergeordnete Abteilung (Name)','text',100,'']],default=>['name'=>['Feldname','text',100,''],'type'=>['Typ','select',['text'=>'Text','number'=>'Zahl','date'=>'Datum','checkbox'=>'Ja/Nein','select'=>'Auswahl'],'text'],'options'=>['Auswahlwerte (eine Zeile je Wert)','textarea',1000,''],'required'=>['Pflichtfeld','checkbox',1,false]]};foreach($fields as $key=>$field)settingsField($key,$field,$row,'data[rows]['.$index.']'); ?></div><button type="button" class="btn btn-outline theme-secondary text-button" data-remove-settings-row>Entfernen</button></fieldset><?php };
 foreach(array_slice($sd['rows'],0,50) as $i=>$row)$renderRow($row,$i); ?></div><template data-settings-row-template><?php $renderRow($rowDefaults,'__INDEX__'); ?></template><button type="button" class="btn btn-outline theme-secondary secondary" data-add-settings-row>+ <?= $section==='structure'?'Abteilung':($section==='fields'?'Feld':'Anrede') ?></button>
